UPDATE dm_doc t SET t.view_chapter_num = (
    SELECT IFNULL(SUM(c.view_num), 0) FROM dm_doc_chapter c WHERE c.doc_id = t.id
) WHERE t.id = #{id}

UPDATE dm_doc t SET t.view_chapter_num = (
    SELECT IFNULL(SUM(c.view_num), 0) FROM dm_doc_chapter c WHERE c.doc_id = t.id
) WHERE t.id = (
    SELECT a.doc_id FROM dm_doc_chapter a WHERE a.id = #{chapterId}
)
